/**
 * The mill's shade cards, as they are: every quality's shades, in card order, under the number
 * written beside each swatch on the card. Read from the photographed cards (one PDF a quality):
 * each swatch's colour is the middle of its cloth, white-balanced against the card's paper, in
 * OKLCH. A phone photo is an approximation of the cloth; a shade can be corrected here by hand.
 * The cards carry numbers only, so each shade is given the nearest of the studio's Indian colour
 * names, unique within its quality (a numeral where two shades share the nearest).
 *
 * Generated by scripts/shade-cards/; edit by hand only to correct a shade.
 */

/** [card number, name, l, c, h] */
export type CardShade = [code: string, name: string, l: number, c: number, h: number];

